function isValidPalindrome(s, k) {
  // A kept palindrome is a common subsequence of s and its reverse, so the
  // longest one is their longest common subsequence (plain LCS table).
  const n = s.length;
  const r = s.split('').reverse().join('');
  const table = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= n; i++)
    for (let j = 1; j <= n; j++)
      table[i][j] = s[i - 1] === r[j - 1] ? table[i - 1][j - 1] + 1 : Math.max(table[i - 1][j], table[i][j - 1]);
  return n - table[n][n] <= k;
}

