function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letter = (alphabet) => String.fromCharCode(97 + int(0, alphabet - 1));
  if (size === 'small') {
    const n = int(1, 10);
    const alphabet = int(1, 4);
    const s = Array.from({ length: n }, () => letter(alphabet)).join('');
    return [s, int(1, n)];
  }
  // Large: a palindrome with some random letters inserted, then k right at the true number of erasures needed.
  const extra = int(0, 120);
  const alphabet = int(2, 26);
  const half = Array.from({ length: Math.floor((1000 - extra) / 2) }, () => letter(alphabet));
  const chars = [...half, ...(rand() < 0.5 ? [letter(alphabet)] : []), ...half.slice().reverse()];
  while (chars.length < 1000) chars.splice(int(0, chars.length), 0, letter(alphabet));
  const s = chars.join('');
  // Longest common subsequence of s and its reverse is the longest palindromic subsequence.
  const r = s.split('').reverse().join('');
  let prev = new Array(s.length + 1).fill(0);
  for (let i = 1; i <= s.length; i++) {
    const cur = new Array(s.length + 1).fill(0);
    for (let j = 1; j <= s.length; j++) cur[j] = s[i - 1] === r[j - 1] ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
    prev = cur;
  }
  const need = s.length - prev[s.length];
  const k = Math.min(s.length, Math.max(1, need + int(-2, 1)));
  return [s, k];
}
